#!/bin/sh
# Usage: pin-checksums.sh [SHA256SUMS] > extension/src/checksums.rs
# Reads `<hex>  <asset>` lines (sha256sum format) and prints checksums.rs.
set -eu
file=${1:-SHA256SUMS}
[ -f "$file" ] || { echo "pin-checksums: cannot read $file" >&2; exit 1; }

echo "// Generated by .github/scripts/pin-checksums.sh from SHA256SUMS. Do not edit by hand."
echo "// Empty in dev builds (no download is attempted)."
echo
echo "pub const PINNED_SHA256: &[(&str, &str)] = &["
n=0
while read -r hex name _; do
  [ -n "$hex" ] || continue
  name=${name#\*}
  case $hex in
    *[!0-9a-fA-F]*) echo "pin-checksums: bad hash for $name" >&2; exit 1 ;;
  esac
  [ "${#hex}" -eq 64 ] || { echo "pin-checksums: hash for $name is not 64 hex digits" >&2; exit 1; }
  case $name in
    *[!A-Za-z0-9._-]*|"") echo "pin-checksums: unexpected asset name '$name'" >&2; exit 1 ;;
  esac
  lower=$(printf '%s' "$hex" | tr 'A-F' 'a-f')
  # rustfmt layout for tuples too long for one line, so `cargo fmt --check` passes.
  printf '    (\n        "%s",\n        "%s",\n    ),\n' "$name" "$lower"
  n=$((n + 1))
done < "$file"
echo "];"
echo
echo "pub fn pinned_sha256(asset: &str) -> Option<&'static str> {"
echo "    PINNED_SHA256"
echo "        .iter()"
echo "        .find(|(name, _)| *name == asset)"
echo "        .map(|(_, hash)| *hash)"
echo "}"
[ "$n" -gt 0 ] || { echo "pin-checksums: no entries in $file" >&2; exit 1; }
